import{_ as p,B as s,c as l,j as t,a as r,G as n,w as d,a5 as o,o as h}from"./chunks/framework.mFcBg5UA.js";const b=JSON.parse('{"title":"前端研发链路之包管理器","titleTemplate":"前端知识图谱","description":"","frontmatter":{"outline":"deep","title":"前端研发链路之包管理器","titleTemplate":"前端知识图谱","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/feMap/developMap/packageManager.html"}]]},"headers":[],"relativePath":"feMap/developMap/packageManager.md","filePath":"feMap/developMap/packageManager.md","lastUpdated":1725898198000}'),k={name:"feMap/developMap/packageManager.md"};function c(g,a,u,m,E,y){const i=s("Graph"),e=s("ClientOnly");return h(),l("div",null,[a[0]||(a[0]=t("h1",{id:"前端研发链路之包管理器",tabindex:"-1"},[r("前端研发链路之包管理器 "),t("a",{class:"header-anchor",href:"#前端研发链路之包管理器","aria-label":'Permalink to "前端研发链路之包管理器"'},"​")],-1)),n(e,null,{default:d(()=>[n(i,{type:"packageManager"})]),_:1}),a[1]||(a[1]=o(`<p>大家好，我是徐徐。今天和大家一起聊聊前端研发链路之包管理器。</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>在现代前端开发中，包管理工具是不可或缺的一部分。随着前端研发链路的不断演进，项目变得愈发复杂，对高效管理依赖项的需求也日益增加。包管理工具的出现，极大地简化了对外部库、框架和依赖项的管理和安装过程，使开发者能够专注于核心业务逻辑的实现。</p><p>本文将探讨当前前端开发中最常用的三种包管理工具：Npm、Yarn 和 Pnpm。通过分析它们的背景、优缺点和使用场景，帮助开发者在前端研发链路中选择最适合自己项目的包管理工具，以提升开发效率和项目的稳定性。</p><h2 id="什么是包管理器" tabindex="-1">什么是包管理器？ <a class="header-anchor" href="#什么是包管理器" aria-label="Permalink to &quot;什么是包管理器？&quot;">​</a></h2><p>包管理器是简化管理和安装 Web 应用所需的外部库、框架和依赖项的工具。它自动化了这些包的获取、安装和版本控制，从而让开发者能够专注于构建应用，而不是手动管理依赖项。</p><p>在前端开发生态系统中，常用的包管理器包括 Npm（Node Package Manager）、Yarn 和 Pnpm。</p><h2 id="它们解决的问题" tabindex="-1">它们解决的问题 <a class="header-anchor" href="#它们解决的问题" aria-label="Permalink to &quot;它们解决的问题&quot;">​</a></h2><ul><li><strong>依赖管理</strong>：自动安装外部库。解析和管理依赖项，提升开发效率。</li><li><strong>版本控制</strong>：确保一致的依赖版本。允许轻松更新，同时保持向后兼容性。</li><li><strong>集中仓库</strong>：提供在线的包目录。简化包的发现、文档访问和社区评分。</li><li><strong>包脚本</strong>：定义构建、测试和部署等自动化任务，优化开发工作流。</li><li><strong>自定义配置</strong>：通过配置文件定制包管理器的行为。</li><li><strong>生态系统和社区支持</strong>：访问大量开源包。社区驱动的维护、更新和支持。</li></ul><h2 id="包管理器的组成部分" tabindex="-1">包管理器的组成部分 <a class="header-anchor" href="#包管理器的组成部分" aria-label="Permalink to &quot;包管理器的组成部分&quot;">​</a></h2><p>包管理器是前端开发中用于管理依赖、自动化任务和简化工作流的重要工具。下面是组成包管理器的关键组件。</p><ul><li><strong>package.json</strong>：包配置文件定义项目的元数据、依赖项和脚本。它包含项目信息如名称、版本、描述以及所需的依赖列表。可以查看 Npm 的 <a href="https://docs.npmjs.com/files/package.json" target="_blank" rel="noreferrer">package.json 文档</a> 了解详细信息。</li><li><strong>依赖管理</strong>：package.json 中的依赖部分指定了项目所需的外部库和框架，包括每个包的名称和相应的版本范围或特定版本。 <ul><li><strong>dependencies</strong>：应用运行所需的依赖。它们在生产环境中安装。例如，一个使用 Express 框架的 Web 应用需要 express 包来处理服务器端路由。</li><li><strong>devDependencies</strong>：开发过程中使用的依赖，不在生产环境中必需。通常包括工具、测试框架和其他开发相关的依赖。例如，Jest 测试库被列为 devDependency，用于在开发过程中进行单元测试。</li><li><strong>peerDependencies</strong>：消费者项目必须安装的依赖。当一个包期望在消费者环境中存在特定版本的另一个包时使用。例如，一个库 my-library 需要消费者项目中安装特定版本的 react。通过在 package.json 中列出 react 作为 peerDependency，my-library 确保安装正确版本的 react，从而保证兼容性和正常运行。</li></ul></li></ul><h2 id="语义化版本控制" tabindex="-1">语义化版本控制 <a class="header-anchor" href="#语义化版本控制" aria-label="Permalink to &quot;语义化版本控制&quot;">​</a></h2><p>语义化版本控制（SemVer）是一种版本控制方案，遵循 MAJOR.MINOR.PATCH 格式，分别表示向后兼容的变化、新特性和错误修复。SemVer 允许开发者定义版本范围或指定精确版本，以确保兼容性和有效地管理更新。<br> 例如：</p><ul><li><code>^1.2.3</code>：允许从 1.2.3 到但不包括 2.0.0 的任何兼容版本。</li><li><code>~1.2.3</code>：允许从 1.2.3 到但不包括 1.3.0 的任何兼容版本。</li><li><code>1.2.3</code>：指定精确版本，确保项目使用该特定版本的依赖。</li></ul><p>SemVer 帮助包管理器准确解析依赖，确保安装兼容的版本，避免破坏性更改或冲突。</p><h2 id="脚本功能" tabindex="-1">脚本功能 <a class="header-anchor" href="#脚本功能" aria-label="Permalink to &quot;脚本功能&quot;">​</a></h2><p>package.json 中的 scripts 部分允许开发者定义自定义命令，用于自动化各种任务。这些脚本可以通过包管理器的 CLI 执行，方便构建、测试、代码检查和部署过程。</p><h2 id="依赖解析" tabindex="-1">依赖解析 <a class="header-anchor" href="#依赖解析" aria-label="Permalink to &quot;依赖解析&quot;">​</a></h2><p>包管理器处理依赖解析，以确保项目中包的版本一致且兼容。通过有效利用依赖树和锁文件，包管理器确保依赖解析的可靠性和一致性，从而实现稳定且可重复的开发环境。</p><ul><li><strong>依赖树</strong>：依赖树表示项目依赖及其相互依赖的层次结构。它可视化包之间的依赖关系，有助于管理冲突和版本约束。 例如：</li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- Project</span></span>
<span class="line"><span>  - Package A@1.0.0</span></span>
<span class="line"><span>    - Package B@^2.0.0</span></span>
<span class="line"><span>      - Package C@^1.1.0</span></span>
<span class="line"><span>  - Package D@~2.5.0</span></span>
<span class="line"><span>    - Package E@^3.0.0</span></span></code></pre></div><ul><li><strong>锁文件</strong>：锁文件（如 Npm 的 package-lock.json，Pnpm 的 Pnpm-lock.yaml 或 Yarn 的 yarn.lock）在依赖解析中起关键作用。它们记录了已安装包及其依赖的确切版本，确保可重复性，防止后续安装过程中发生意外更改。 例如：</li></ul><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project-name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;lockfileVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;package-a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;package-b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;package-b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.1.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;package-c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;package-c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>锁文件确保项目依赖的后续安装基于相同版本，避免由于版本变化引起的不一致和意外行为。</p><h2 id="包安装" tabindex="-1">包安装 <a class="header-anchor" href="#包安装" aria-label="Permalink to &quot;包安装&quot;">​</a></h2><p>包管理器处理包的安装和从中央仓库的获取。</p><ul><li><strong>注册表</strong>：包管理器的注册表作为包的集中仓库。它包含大量开源库和框架，开发者可以访问并将其包含在项目中。注册表允许包管理器获取和下载包，解析依赖并管理版本。 例如： <ul><li>Npm 使用默认的 Npm 注册表（registry.Npmjs.org）。</li><li>Yarn 使用默认的 Yarn 注册表（registry.yarnpkg.com）。</li><li>Pnpm 使用默认的 Npm 注册表（registry.Npmjs.org）。</li></ul></li><li><strong>缓存</strong>：包管理器通常维护已下载包的本地缓存。缓存加快后续安装速度，减少对网络请求的依赖，通过本地存储包实现。</li></ul><h2 id="命令行界面" tabindex="-1">命令行界面 <a class="header-anchor" href="#命令行界面" aria-label="Permalink to &quot;命令行界面&quot;">​</a></h2><p>包管理器的 CLI 提供命令行界面与工具功能进行交互。</p><ul><li><strong>CLI命令</strong>：包管理器提供多种命令执行常见任务，如安装包、更新依赖、执行脚本和管理包管理器配置。例如，<code>Npm install</code> 或 <code>yarn upgrade</code>。</li><li><strong>自定义</strong>：CLI 允许开发者通过配置文件自定义包管理器行为。这些文件使开发者能够定义设置，如包来源、认证凭据和代理配置。 例如，Npm 使用 <code>.Npmrc</code> 文件自定义配置。开发者可以在此文件中指定设置，如注册表 URL、认证令牌和代理配置。类似地，Yarn 使用 <code>.yarnrc</code> 文件配置各种选项。 例如：</li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .Npmrc</span></span>
<span class="line"><span># Custom registry source</span></span>
<span class="line"><span>registry=https://my-custom-registry.com/</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># Authentication token</span></span>
<span class="line"><span>//my-custom-registry.com/:_authToken=1234567890</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># Proxy settings</span></span>
<span class="line"><span>https-proxy=http://proxy.example.com/</span></span>
<span class="line"><span>http-proxy=http://proxy.example.com/</span></span></code></pre></div><p>通过修改这些配置文件，可以根据项目要求定制包管理器行为，例如使用自定义注册表、应用认证令牌或配置代理设置。</p><h2 id="npm、yarn-和-pnpm-对比" tabindex="-1">Npm、Yarn 和 Pnpm 对比 <a class="header-anchor" href="#npm、yarn-和-pnpm-对比" aria-label="Permalink to &quot;Npm、Yarn 和 Pnpm 对比&quot;">​</a></h2><p>包管理器在软件项目的开发和管理中发挥了重要作用。下面是对三个流行的包管理器——Npm、Yarn 和 Pnpm 的简要历史和演变的探索。</p><h3 id="npm" tabindex="-1">Npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;Npm&quot;">​</a></h3><p>Npm（Node Package Manager）于 2010 年作为 Node.js 的默认包管理器创建。它是前端社区中使用最广泛的包管理器。Npm 附带在 Node.js 中，并提供了一个庞大的包生态系统。使用 Npm 安装依赖项非常简单，只需运行 <code>Npm install</code>。</p><p>Npm 因 Node.js 作为流行的 JavaScript 运行时环境的兴起而迅速流行。Npm 注册表成为开源包的首选来源，促成了庞大库和框架生态系统的增长。</p><p><strong>优点</strong>：</p><ul><li>广泛采用的包管理器，具有庞大的包生态系统。</li><li>Node.js 的默认包管理器，在前端社区中广泛使用。</li><li>活跃的社区支持和频繁的包更新。</li></ul><h3 id="yarn" tabindex="-1">Yarn <a class="header-anchor" href="#yarn" aria-label="Permalink to &quot;Yarn&quot;">​</a></h3><p>Yarn 由 Facebook 于 2016 年开发（虽然现在不再由 Facebook 运营），作为对 Npm 某些限制和挑战的回应。<br> Yarn 引入了并行包安装，显著提高了安装速度。通过锁文件（yarn.lock）实现了确定性的依赖解析，确保不同环境中的一致安装。</p><p>它还引入了缓存依赖项，使 Yarn 能够进行离线安装，允许开发者在没有互联网连接的情况下安装包。最后，它带来了即插即用功能，使包在不显式安装的情况下使用，减少磁盘空间占用，加快开发过程。</p><p><strong>优点</strong>：</p><ul><li>通过并行安装和全局包缓存优化性能。</li><li>支持在单个仓库中管理多个包的工作区。</li><li>即插即用（PnP）功能使包在不显式安装的情况下使用，减少磁盘空间占用。</li></ul><h3 id="pnpm" tabindex="-1">Pnpm <a class="header-anchor" href="#pnpm" aria-label="Permalink to &quot;Pnpm&quot;">​</a></h3><p>Pnpm 于 2016 年推出，通过优化磁盘空间使用和安装时间与众不同。它还提供了对 monorepos 和工作区的优秀支持，使得在单个仓库中管理多个包变得高效。与 Npm 和 Yarn 不同，Pnpm 是注册表无关的，允许开发者配置和使用任何兼容的注册表作为包来源。</p><p>Npm 和 Yarn 的早期版本将依赖项存储在项目特定的 node_modules 目录中。这意味着当多个项目具有相同或重叠的依赖项时，每个项目最终都会有这些依赖项的副本，导致包的显著重复。<br> Yarn 的更新版本通过其即插即用功能解决了这个问题。</p><p><strong>优点</strong>：</p><ul><li>通过共享依赖的独特方法减少磁盘空间使用。</li><li>通过使用硬链接和符号链接加快安装时间。</li><li>对 monorepos 和工作区提供出色支持。</li><li>注册表无关，允许配置和使用任何兼容的注册表作为包来源。</li></ul><h3 id="整体对比表" tabindex="-1">整体对比表 <a class="header-anchor" href="#整体对比表" aria-label="Permalink to &quot;整体对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>Npm</th><th>Yarn</th><th>Pnpm</th></tr></thead><tbody><tr><td>普及度</td><td>高</td><td>高</td><td>增长中</td></tr><tr><td>生态系统</td><td>大</td><td>大</td><td>扩展中</td></tr><tr><td>依赖管理</td><td>package.json</td><td>package.json</td><td>package.json</td></tr><tr><td>CLI</td><td>全面</td><td>类似于 Npm</td><td>类似于 Npm</td></tr><tr><td>包脚本</td><td>✅</td><td>不特定</td><td>不特定</td></tr><tr><td>注册表</td><td>Npm registry</td><td>Yarn registry</td><td>可自定义</td></tr><tr><td>速度</td><td>中等</td><td>快</td><td>非常快</td></tr><tr><td>锁文件</td><td>package-lock.json</td><td>yarn.lock</td><td>Pnpm-lock.yaml</td></tr><tr><td>性能</td><td>中等</td><td>快</td><td>非常快</td></tr><tr><td>磁盘空间</td><td>中等</td><td>中等</td><td>低</td></tr><tr><td>离线支持</td><td>有限（通过 Npm ci）</td><td>✅</td><td>✅</td></tr><tr><td>并行安装</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>工作区</td><td>✅（自 Npm 7）</td><td>✅</td><td>✅</td></tr><tr><td>即插即用（PnP）</td><td>❌</td><td>✅</td><td>❌</td></tr><tr><td>Monorepo 支持</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>社区支持</td><td>活跃</td><td>活跃</td><td>增长中</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>选择合适的包管理工具对于前端开发的高效性和项目的稳定性至关重要。Npm 作为历史最悠久的包管理器，拥有庞大的社区和丰富的包资源，适合大多数开发者。Yarn 通过并行安装、确定性依赖解析和离线支持等特性，显著提升了开发效率。而 Pnpm 以独特的依赖共享方法和对 monorepos 的优异支持，进一步优化了磁盘空间使用和安装速度。</p><p>无论是选择 Npm、Yarn 还是 Pnpm，都需要根据项目的具体需求和开发团队的习惯来做出最佳决策。通过了解各包管理工具的特点和优势，开发者可以更好地管理项目依赖，提升开发效率，确保项目的稳定运行。</p>`,55))])}const C=p(k,[["render",c]]);export{b as __pageData,C as default};
